"""Private authored-dialogue reader; no game execution or state inference."""
from pathlib import Path
from collections import defaultdict,deque
import sqlite3,json,hashlib
root=Path(__file__).resolve().parent.parent;out=Path(__file__).resolve().parent
dbpath=root/'reference-materials/disco/public-dialogue-db/disco.db'
assert hashlib.sha256(dbpath.read_bytes()).hexdigest()=='ae364f994f1afbe6024a8c7e3f8402a73de329d2866a543a81eb42ebceeb4ae5'
db=sqlite3.connect('file:'+str(dbpath)+'?mode=ro',uri=True);db.row_factory=sqlite3.Row;db.execute('PRAGMA query_only=ON')
def rows(sql,params=()):return [dict(x) for x in db.execute(sql,params)]
actors={a['id']:a['name'] for a in rows('select id,name from actors')}
# Topic boundaries are existing return hubs, not word-count truncations.
plan=[
 {'subject':72,'units':[{'cid':992,'roots':[0],'stops':[]}],'reason':'Bereavement notification and the children; whole existing conversation, including alternate responses.'},
 {'subject':3,'units':[{'cid':659,'roots':[31,35],'stops':[3]}],'reason':'Disposition of the body and responsibility for the case, stopping at the existing general inspection hub. Also appears with Billie in the first unit.'},
 {'subject':6,'units':[{'cid':1274,'roots':[317],'stops':[]}],'reason':'Attempting to leave opens the debt dispute; include every ensuing branch to its endpoint.'},
 {'subject':5,'units':[{'cid':1038,'roots':[371],'stops':[]},{'cid':1037,'roots':[2,115,23],'stops':[17]}],'reason':'Signature request with every address variant, then separate post-letter context and fine-print dispute; these are separate authored units, not an executed timeline.'},
 {'subject':11,'units':[{'cid':759,'roots':[300],'stops':[439]}],'reason':'The takeover report through escalation and response, stopping at the existing subsequent conversation hub.'},
 {'subject':18,'units':[{'cid':865,'roots':[0],'stops':[]}],'reason':'Whole existing conversation about his relationship, pressure and agency; not a merged path through all choices.'},
]
private=[];reader=[];pins=[];all_rows=[];unresolved={(1037,10),(1037,114),(765,1140),(765,1203)}
for person_i,p in enumerate(plan,1):
    group={'subject':actors[p['subject']],'units':[]};reader.append(group)
    for unit_i,spec in enumerate(p['units'],1):
        cid=spec['cid'];nodes={n['id']:n for n in rows('select * from temp_table where conversationid=? order by id',(cid,))}
        links=rows('select rowid,* from dlinks where originconversationid=? order by rowid',(cid,));edges=defaultdict(list)
        for l in links:edges[l['origindialogueid']].append(l)
        q=deque(spec['roots']);selected=[];seen=set();bounds=[]
        while q:
            n=q.popleft()
            if n in seen:continue
            seen.add(n)
            if n in spec['stops'] or (cid,n) in unresolved:continue
            assert n in nodes;selected.append(n)
            for l in edges[n]:
                if l['destinationconversationid']!=cid or l['destinationdialogueid'] in spec['stops'] or (cid,l['destinationdialogueid']) in unresolved:
                    bounds.append(l)
                else:q.append(l['destinationdialogueid'])
        label={n:f'N{i:03}' for i,n in enumerate(selected,1)}
        unit={'id':f'U{person_i}.{unit_i}','entry':[label[n] for n in spec['roots']],'nodes':[],'boundary_note':'Leaving this selected authored unit ends the excerpt; linked material outside is not represented as an executed event.'}
        group['units'].append(unit)
        audit={'subject_id':p['subject'],'reason':p['reason'],'spec':spec,'selected_ids':selected,'boundaries':bounds,'incoming_from_outside':[],'raw_nodes':[],'alternates':[],'checks':[],'modifiers':[]}
        for n in selected:
            v=nodes[n];alts=rows('select rowid,* from alternates where conversationid=? and dialogueid=? order by rowid',(cid,n));checks=rows('select * from checks where conversationid=? and dialogueid=?',(cid,n));mods=rows('select * from modifiers where conversationid=? and dialogueid=?',(cid,n))
            audit['raw_nodes'].append(v);audit['alternates'].extend(alts);audit['checks'].extend(checks);audit['modifiers'].extend(mods)
            for link in rows('select * from dlinks where destinationconversationid=? and destinationdialogueid=?',(cid,n)):
                if link['originconversationid']!=cid or link['origindialogueid'] not in label:audit['incoming_from_outside'].append(link)
            raw=v['dialoguetext'];prose=raw if raw is not None and raw.strip() not in ('','0') else None
            item={'id':label[n],'speaker':actors.get(v['actor'],'Unspecified'),'text':prose,'state_dependent':bool(v['conditionstring']),'alternates':[{'variant':f'V{i:02}','text':a['alternateline'],'state_dependent':bool(a['condition'])} for i,a in enumerate(alts,1)],'continuations':[label[l['destinationdialogueid']] if l['destinationconversationid']==cid and l['destinationdialogueid'] in label else 'outside selected unit' for l in edges[n]],'conditional_routing':bool(v['isgroup'] or v['conditionstring'] or checks),'check_authored':bool(checks)}
            unit['nodes'].append(item)
            fields=[('dialoguetext',raw)]+[(f'alternates.rowid={a["rowid"]}.alternateline',a['alternateline']) for a in alts]
            for field,text in fields:
                b=('' if text is None else text).encode();pins.append({'unit':unit['id'],'node':label[n],'coordinate':f'{cid}:{n}','field':field,'null':text is None,'utf8_bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
        private.append(audit)
package={'notice':'Authored dialogue with alternatives, not a played transcript. Listed paths and state variants need not be simultaneously available or executable. Separate units are not asserted to occur in the displayed order. Parent-state requirements may apply even when a line has no own state condition. No spoken text has been added.','subjects':reader}
for name,value in [('reader.json',package),('private-source-audit.json',private),('field-pins.json',pins)]:
    b=json.dumps(value,ensure_ascii=False,indent=2).encode();assert json.loads(b)==value;(out/name).write_bytes(b+b'\n')
manifest={'status':'constructed; independent source/context adequacy review pending; not blind-comparison ready','database_sha256':hashlib.sha256(dbpath.read_bytes()).hexdigest(),'source_inference':'Pinned third-party extraction with only a limited prior displayed-text cross-check; not official full-game certification. Runtime execution, alternate priority and state satisfiability are not measured.','subjects':len(reader),'units':len(private),'nodes':sum(len(a['raw_nodes']) for a in private),'alternates':sum(len(a['alternates']) for a in private),'text_fields':len(pins),'source_word_count':sum(len((n['dialoguetext'] or '').split()) for a in private for n in a['raw_nodes']),'reader_sha256':hashlib.sha256((out/'reader.json').read_bytes()).hexdigest(),'entry_unconfirmed_rows':'The previously identified four rows remain in the original DB and private audit; none is silently inserted into a selected scene.','excluded_context':'All outgoing and incoming excerpt boundaries are explicit in private-source-audit.json. Six names/counts alone do not establish adequate character coverage.','role':'Coordinator source extraction only. No benchmark/reference/status change. Full dialogue analysis remains private and is excluded from the game and distribution.'}
(out/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(json.dumps(manifest,ensure_ascii=False))

